(x, y, t) => {
  const cx = 240, cy = 120;
  let wx = 0, wy = 0, amp = 18, freq = 0.016, spd = 0.3;
  for (let o = 0; o < 3; o++) {
    wx += Math.sin(x * freq + t * spd) * amp * Math.cos(y * freq * 0.7 - t * spd * 0.8);
    wy += Math.cos(y * freq - t * spd * 0.9) * amp * Math.sin(x * freq * 0.8 + t * spd * 1.1);
    amp *= 0.5; freq *= 2.0; spd *= 1.25;
  }
  const sx = x + wx, sy = y + wy;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 1.2],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 2.5],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 3.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 5.0],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 6.2],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65)*50, 0.11, 2.1, 1.8],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75+4)*60, 0.085, 2.4, 4.5]
  ];
  let aS = 0, iS = 0, hS = 0;
  for (const [sX, sY, f, sp, ph] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    const w1 = Math.sin(d*f - t*sp + ph);
    const w2 = Math.sin(d*f*2.2 + t*sp*0.7 - ph*0.5) * 0.35;
    aS += w1 + w2;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5 + ph) * 0.8 + Math.sin(d*f*1.4 - t*sp*0.4 + ph*0.3) * 0.25;
    hS += Math.sin(d*f*0.35 + t*sp*0.25 + ph*2) * 0.4;
  }
  const act = aS/13.5, inh = iS/8.4, harm = hS/3.2;
  const bg1 = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))*0.5;
  const bg2 = Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2;
  const bg3 = Math.sin(sx*0.08+t*1.5)*Math.sin(sy*0.06-t*1.2)*0.25;
  const bg = bg1 + bg2 + bg3;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const sp1 = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2))*0.35;
  const sp2 = Math.sin(dist*0.08+ang*2-t*2.5)*Math.cos(dist*0.03-ang*5+t*1.8)*0.25;
  const raw = act - inh*0.65 + bg*0.28 + sp1 + sp2 + harm*0.18;
  const r1 = Math.tanh(raw*2.2);
  const r2 = Math.tanh((r1*1.4 + Math.sin(sx*0.1+sy*0.08+t*1.8)*0.35 - r1*r1*0.45)*2);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.25;
  let minD = 999;
  for (let i = 0; i < src.length; i += 2) { const d = Math.sqrt((sx-src[i][0])**2 + (sy-src[i][1])**2); if (d < minD) minD = d; }
  const vor = Math.sin(minD*0.14 - t*1.5)*0.25;
  const blend = r2*0.5 + r1*0.2 + cell*0.18 + vor*0.12;
  const v = blend*0.5+0.5;
  const pal = [[4,10,42],[10,42,78],[16,82,98],[22,128,115],[80,155,85],[165,175,55],[210,155,50],[195,90,58],[150,48,62],[85,28,52],[35,16,55],[4,10,42]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.72 + Math.sin(Math.abs(r1)*Math.PI)*0.28;
  const edge = Math.abs(r2) > 0.6 ? 1.18 : Math.abs(r2) > 0.35 ? 1.06 : 1.0;
  const glow = Math.max(0, r1 - 0.4) * 0.6;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge + glow*55)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge + glow*25)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge + glow*75)|0)
  ];
}
